/* Map & Geography maps.
 *
 * Draws the small locator map at the top of every Map & Geography pane. The
 * pane's HTML carries the place keys and the write-ups; this file carries the
 * coastlines and the coordinates, and turns them into an SVG.
 *
 * Generated by build_mapgeo.py from mapgeo_basemap.py and mapgeo_places.py.
 * Do not edit this file directly, edit mapgeo.template.js and rebuild.
 *
 * Coastlines, lakes and rivers are Natural Earth, which is public domain.
 *
 * Notes on the approach
 * ---------------------
 * The SVG is laid out in CSS pixels rather than in degrees, so a viewBox of
 * "0 0 640 412" on a 640px-wide figure. Labels then keep the same size on a
 * phone and on a desktop, which a geographic viewBox cannot do, and the
 * collision arithmetic is in the same units as the text it is avoiding. The
 * cost is a re-render on resize, which a ResizeObserver handles and which also
 * covers the first time the pane is shown, since an inactive tab is
 * display:none and measures zero.
 *
 * Only the basemap is scaled: it lives in a <g transform> and uses
 * non-scaling-stroke so coastlines stay hairlines at every zoom.
 */
(function () {
    'use strict';

    var Q = __QUANT__;
    var ALPHA = '__ALPHA__';
    /* Projected frame of the basemap, in Mercator degrees with y already
     * flipped for SVG. Nothing outside it exists in the data, so views are
     * clamped to it rather than showing empty space. */
    var FRAME = __FRAME__;
    var BASE = __BASE__;
    /* key -> [name, lat, lon, kind]. The write-ups are in the page, not here. */
    var PLACES = __PLACES__;

    /* The figure takes its shape from the chapter. Israel is long and narrow, so
     * a fixed wide map crops the Dead Sea off a Galilee-to-Jerusalem view; the
     * voyage in Acts 27 needs the opposite. Clamped at both ends so no map is
     * either a letterbox or a column. */
    var ASPECT_MIN = 1.15;
    var ASPECT_MAX = 1.95;
    var ASPECT_FLAT = 1.5;  /* used when the places sit on top of each other */
    /* Degrees of longitude. Below about three degrees a Levant map loses the
     * coast, the Sea of Galilee or the Dead Sea, and a map of the hill country
     * with no recognisable feature on it tells a reader nothing. Chapters whose
     * places sit inside a single town are zoomed out to this and rely on the
     * cluster label instead. */
    var MIN_SPAN = 3.0;
    var MAX_H = 520;        /* px, so a wide desktop pane does not get a mural */
    var MIN_H = 190;        /* px, below which labels have nowhere to go */
    var PAD = 0.22;         /* share of the span added around the pins */
    var CLUSTER = 30;       /* px; closer pins share one label */
    var LINE = 15;          /* px; minimum vertical gap between two labels */
    var FONT = 12;          /* px; label size, also set in CSS for consistency */

    var IDX = {};
    for (var i = 0; i < ALPHA.length; i++) { IDX[ALPHA.charAt(i)] = i; }

    var cache = null;       /* decoded basemap, built once on first render */

    /* ---------------------------------------------------------------- data */

    function decode(s) {
        /* Zig-zag base-32 varints, delta encoded, two per point. */
        var pts = [], x = 0, y = 0, i = 0, n = s.length, v, sh, d;
        while (i < n) {
            v = 0; sh = 0;
            do { d = IDX[s.charAt(i++)]; v += (d & 31) * Math.pow(2, sh); sh += 5; }
            while (d >= 32);
            x += (v % 2) ? -(v + 1) / 2 : v / 2;
            v = 0; sh = 0;
            do { d = IDX[s.charAt(i++)]; v += (d & 31) * Math.pow(2, sh); sh += 5; }
            while (d >= 32);
            y += (v % 2) ? -(v + 1) / 2 : v / 2;
            pts.push(x / Q, y / Q);
        }
        return pts;
    }

    function toPath(coords, close) {
        var d = '', j;
        for (j = 0; j < coords.length; j += 2) {
            d += (j ? 'L' : 'M') + coords[j].toFixed(3) + ',' + coords[j + 1].toFixed(3);
        }
        return d + (close ? 'Z' : '');
    }

    function basemap() {
        if (cache) { return cache; }
        cache = { land: [], lakes: [], rivers: [] };
        var layer, k;
        for (layer in BASE) {
            if (!Object.prototype.hasOwnProperty.call(BASE, layer)) { continue; }
            for (k = 0; k < BASE[layer].length; k++) {
                cache[layer].push(toPath(decode(BASE[layer][k]), layer !== 'rivers'));
            }
        }
        return cache;
    }

    /* ---------------------------------------------------------- projection */

    function projectY(lat) {
        /* Web Mercator, negated so north is up in SVG coordinates. */
        return -(Math.log(Math.tan(Math.PI / 4 + lat * Math.PI / 360)) * 180 / Math.PI);
    }

    function view(points, w, h) {
        /* The window on the world for one chapter: centred on its places, never
         * tighter than MIN_SPAN so a single pin still has a coastline near it,
         * matched to the figure's aspect, and kept inside the basemap. */
        var x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity, i, p;
        for (i = 0; i < points.length; i++) {
            p = points[i];
            if (p.x < x0) { x0 = p.x; }
            if (p.x > x1) { x1 = p.x; }
            if (p.y < y0) { y0 = p.y; }
            if (p.y > y1) { y1 = p.y; }
        }
        var cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
        var sx = (x1 - x0) * (1 + 2 * PAD), sy = (y1 - y0) * (1 + 2 * PAD);
        var aspect = w / h;
        if (sx < MIN_SPAN) { sx = MIN_SPAN; }
        if (sy < MIN_SPAN / aspect) { sy = MIN_SPAN / aspect; }
        if (sx / sy < aspect) { sx = sy * aspect; } else { sy = sx / aspect; }

        var fw = FRAME.x1 - FRAME.x0, fh = FRAME.y1 - FRAME.y0;
        if (sx > fw) { sx = fw; sy = sx / aspect; }
        if (sy > fh) { sy = fh; sx = sy * aspect; }
        cx = Math.max(FRAME.x0 + sx / 2, Math.min(FRAME.x1 - sx / 2, cx));
        cy = Math.max(FRAME.y0 + sy / 2, Math.min(FRAME.y1 - sy / 2, cy));
        return { left: cx - sx / 2, top: cy - sy / 2, sx: sx, sy: sy, k: w / sx };
    }

    /* ------------------------------------------------------------ markers */

    function marker(kind, x, y) {
        /* A dot means a site you could stand on. A ring means a region, a
         * river or a sea, where a single point is only an anchor. */
        if (kind === 'city' || kind === 'island') {
            return '<circle class="gm-dot" cx="' + x + '" cy="' + y + '" r="4.2"/>';
        }
        if (kind === 'mountain') {
            return '<path class="gm-dot" d="M' + x + ',' + (y - 5.4) +
                'L' + (x + 5) + ',' + (y + 3.6) + 'L' + (x - 5) + ',' + (y + 3.6) + 'Z"/>';
        }
        return '<circle class="gm-ring" cx="' + x + '" cy="' + y + '" r="5.2"/>';
    }

    /* How specific a coordinate is. A cluster takes the name and the marker of
     * its most specific member, so Joppa beats the Mediterranean rather than
     * being hidden behind it, and a group containing a town is drawn as a town.
     */
    var RANK = { city: 0, island: 1, mountain: 2, river: 3, water: 4, region: 5 };

    function group(marks) {
        /* Jerusalem, the Temple Mount, Gethsemane, Calvary and the Mount of
         * Olives are within two miles of each other. At any zoom that also
         * shows the Jordan they are one blob, so they get one label and the
         * write-ups below the map do the naming. */
        var groups = [], i, j, g, m, done;
        for (i = 0; i < marks.length; i++) {
            m = marks[i];
            done = false;
            for (j = 0; j < groups.length; j++) {
                g = groups[j];
                if (Math.abs(g.x - m.x) < CLUSTER && Math.abs(g.y - m.y) < CLUSTER) {
                    g.members.push(m);
                    done = true;
                    break;
                }
            }
            if (!done) {
                groups.push({ x: m.x, y: m.y, members: [m] });
            }
        }
        for (i = 0; i < groups.length; i++) {
            g = groups[i];
            g.members.sort(function (a, b) { return RANK[a.kind] - RANK[b.kind]; });
            /* Draw the group where its most specific member actually is. */
            g.x = g.members[0].x;
            g.y = g.members[0].y;
            g.kind = g.members[0].kind;
        }
        return groups;
    }

    function label(g) {
        var n = g.members.length;
        return n === 1 ? g.members[0].name : g.members[0].name + ' +' + (n - 1);
    }

    function overlaps(a, b) {
        return a.x0 < b.x1 && a.x1 > b.x0 && a.y0 < b.y1 && a.y1 > b.y0;
    }

    function labelBox(g, side, width, dy, h) {
        var ly = g.y + FONT * 0.35 + dy;
        if (ly < FONT || ly > h - 5) { return null; }
        var lx = side === 'right' ? g.x + 10 : g.x - 10;
        return {
            side: side, lx: lx, ly: ly,
            x0: side === 'right' ? lx : lx - width,
            x1: side === 'right' ? lx + width : lx,
            y0: ly - FONT * 0.85, y1: ly + FONT * 0.3
        };
    }

    function place(groups, w, h) {
        /* First fit from a short list of candidate positions: beside the pin on
         * whichever side has room, then a line up or down, and so on. Every
         * candidate is tested against the labels already placed, against every
         * other pin's marker, and against the scale bar, because the previous
         * version only avoided other labels and cheerfully wrote "Galilee"
         * across the dot for Capernaum. */
        var taken = [{ x0: 0, x1: 150, y0: h - 26, y1: h }];   /* the scale bar */
        var dots = [], i, j, g;
        for (i = 0; i < groups.length; i++) {
            dots.push({ g: groups[i], x0: groups[i].x - 7, x1: groups[i].x + 7,
                        y0: groups[i].y - 7, y1: groups[i].y + 7 });
        }
        groups.sort(function (a, b) { return a.y - b.y; });

        var steps = [0, -LINE, LINE, -2 * LINE, 2 * LINE, -3 * LINE, 3 * LINE];
        for (i = 0; i < groups.length; i++) {
            g = groups[i];
            g.text = label(g);
            var width = g.text.length * FONT * 0.56;
            var order = (g.x + 10 + width > w - 6) ? ['left', 'right']
                                                   : ['right', 'left'];
            var chosen = null, fallback = null, s, d, box, clash;
            for (d = 0; d < steps.length && !chosen; d++) {
                for (s = 0; s < order.length && !chosen; s++) {
                    box = labelBox(g, order[s], width, steps[d], h);
                    if (!box || box.x0 < 4 || box.x1 > w - 4) { continue; }
                    if (!fallback) { fallback = box; }
                    clash = false;
                    for (j = 0; j < taken.length && !clash; j++) {
                        clash = overlaps(box, taken[j]);
                    }
                    for (j = 0; j < dots.length && !clash; j++) {
                        clash = dots[j].g !== g && overlaps(box, dots[j]);
                    }
                    if (!clash) { chosen = box; }
                }
            }
            box = chosen || fallback || labelBox(g, 'right', width, 0, h);
            taken.push(box);
            g.side = box.side;
            g.lx = box.lx;
            g.ly = box.ly;
            /* Only draw a leader once the label has moved far enough that it
             * would otherwise look attached to the wrong pin. */
            g.leader = Math.abs(box.ly - (g.y + FONT * 0.35)) > 6;
        }
        return groups;
    }

    /* ---------------------------------------------------------- scale bar */

    function scaleBar(v, w, h) {
        /* Distances are the whole point of several of the write-ups, so the map
         * should let a reader check them. Miles, because that is what the notes
         * use. */
        var milesPerDeg = 69.17 * Math.cos(latOf(v.top + v.sy / 2) * Math.PI / 180);
        var target = v.sx * milesPerDeg * 0.28;
        var steps = [1, 2, 5, 10, 20, 25, 50, 100, 200, 250, 500, 1000, 2000];
        var miles = steps[steps.length - 1], i;
        for (i = 0; i < steps.length; i++) {
            if (steps[i] >= target) { miles = steps[i]; break; }
        }
        var px = miles / milesPerDeg * v.k;
        if (px < 24 || px > w * 0.5) { return ''; }
        var x = 12, y = h - 12;
        return '<g class="gm-scale">' +
            '<path d="M' + x + ',' + (y - 4) + 'v4h' + px + 'v-4"/>' +
            '<text x="' + (x + px / 2) + '" y="' + (y - 7) + '">' + miles + ' mi</text>' +
            '</g>';
    }

    function latOf(y) {
        /* Inverse Mercator, for the scale bar's latitude correction. */
        return (2 * Math.atan(Math.exp(-y * Math.PI / 180)) - Math.PI / 2) * 180 / Math.PI;
    }

    /* ------------------------------------------------------------- render */

    function keysOf(el) {
        var raw = (el.getAttribute('data-places') || '').split(',');
        var keys = [], i, k;
        for (i = 0; i < raw.length; i++) {
            k = raw[i].trim();
            if (k && PLACES[k]) { keys.push(k); }
        }
        return keys;
    }

    function shapeOf(marks) {
        var x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity, i, m;
        for (i = 0; i < marks.length; i++) {
            m = marks[i];
            if (m.gx < x0) { x0 = m.gx; }
            if (m.gx > x1) { x1 = m.gx; }
            if (m.gy < y0) { y0 = m.gy; }
            if (m.gy > y1) { y1 = m.gy; }
        }
        var sx = x1 - x0, sy = y1 - y0;
        if (sx < 0.05 && sy < 0.05) { return ASPECT_FLAT; }
        if (sy < 0.05) { return ASPECT_MAX; }
        return Math.max(ASPECT_MIN, Math.min(ASPECT_MAX, sx / sy));
    }

    function render(el) {
        var w = Math.round(el.clientWidth);
        if (!w) { return false; }
        var keys = keysOf(el);
        if (!keys.length) { return true; }

        var marks = [], i, p;
        for (i = 0; i < keys.length; i++) {
            p = PLACES[keys[i]];
            marks.push({ key: keys[i], name: p[0], kind: p[3],
                         gx: p[2], gy: projectY(p[1]) });
        }
        var h = Math.max(MIN_H, Math.min(MAX_H, Math.round(w / shapeOf(marks))));
        var v = view(marks.map(function (m) { return { x: m.gx, y: m.gy }; }), w, h);
        for (i = 0; i < marks.length; i++) {
            marks[i].x = (marks[i].gx - v.left) * v.k;
            marks[i].y = (marks[i].gy - v.top) * v.k;
        }

        var maps = basemap();
        var svg = '<svg class="gm-svg" viewBox="0 0 ' + w + ' ' + h + '" width="' + w +
            '" height="' + h + '" role="img" aria-label="Map showing ' +
            marks.map(function (m) { return m.name; }).join(', ') + '">';
        svg += '<rect class="gm-sea" x="0" y="0" width="' + w + '" height="' + h + '"/>';
        svg += '<g transform="translate(' + (-v.left * v.k).toFixed(2) + ',' +
            (-v.top * v.k).toFixed(2) + ') scale(' + v.k.toFixed(5) + ')">';
        for (i = 0; i < maps.land.length; i++) {
            svg += '<path class="gm-land" d="' + maps.land[i] + '"/>';
        }
        for (i = 0; i < maps.rivers.length; i++) {
            svg += '<path class="gm-river" d="' + maps.rivers[i] + '"/>';
        }
        for (i = 0; i < maps.lakes.length; i++) {
            svg += '<path class="gm-lake" d="' + maps.lakes[i] + '"/>';
        }
        svg += '</g>';
        svg += scaleBar(v, w, h);

        var groups = place(group(marks), w, h);
        for (i = 0; i < groups.length; i++) {
            var g = groups[i];
            var ids = g.members.map(function (m) { return m.key; }).join(' ');
            /* Not focusable on purpose. The <svg> is role="img" with an
             * aria-label naming every place, so its insides are already hidden
             * from assistive technology; making each pin a tab stop would add a
             * dozen unlabelled ones per chapter and activate nothing. The
             * write-up list below the map is the accessible path. */
            svg += '<g class="gm-pin" data-places="' + ids + '">';
            if (g.leader) {
                svg += '<path class="gm-leader" d="M' + g.x.toFixed(1) + ',' +
                    g.y.toFixed(1) + 'L' + g.lx.toFixed(1) + ',' + g.ly.toFixed(1) + '"/>';
            }
            svg += marker(g.kind, g.x.toFixed(1), g.y.toFixed(1));
            svg += '<text class="gm-label" x="' + g.lx.toFixed(1) + '" y="' +
                g.ly.toFixed(1) + '" text-anchor="' +
                (g.side === 'right' ? 'start' : 'end') + '">' +
                escapeText(g.text) + '</text>';
            svg += '</g>';
        }
        svg += '</svg>';

        el.innerHTML = svg;
        el.setAttribute('data-rendered', String(w));
        return true;
    }

    function escapeText(s) {
        return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

    /* -------------------------------------------------- linking to notes */

    function noteFor(root, key) {
        return root.querySelector('[data-place="' + key + '"]');
    }

    function highlight(root, keys, on) {
        var i, note;
        for (i = 0; i < keys.length; i++) {
            note = noteFor(root, keys[i]);
            if (note) { note.classList.toggle('gm-on', on); }
        }
        var pins = root.querySelectorAll('.gm-pin');
        for (i = 0; i < pins.length; i++) {
            var mine = pins[i].getAttribute('data-places').split(' ');
            var hit = keys.some(function (k) { return mine.indexOf(k) >= 0; });
            if (hit) { pins[i].classList.toggle('gm-on', on); }
        }
    }

    function wire(pane) {
        /* Pins and the place names in the prose point at each other. The prose
         * names are real anchors to the write-up below, so they still work with
         * no script; this only stops the jump and highlights instead. */
        pane.addEventListener('mouseover', function (e) {
            var pin = e.target.closest ? e.target.closest('.gm-pin') : null;
            if (pin) { highlight(pane, pin.getAttribute('data-places').split(' '), true); }
            var ref = e.target.closest ? e.target.closest('.geo-ref, .geo-notes li') : null;
            if (ref) { highlight(pane, [keyOf(ref)], true); }
        });
        pane.addEventListener('mouseout', function (e) {
            var pin = e.target.closest ? e.target.closest('.gm-pin') : null;
            if (pin) { highlight(pane, pin.getAttribute('data-places').split(' '), false); }
            var ref = e.target.closest ? e.target.closest('.geo-ref, .geo-notes li') : null;
            if (ref) { highlight(pane, [keyOf(ref)], false); }
        });
        pane.addEventListener('click', function (e) {
            var ref = e.target.closest ? e.target.closest('.geo-ref') : null;
            if (!ref) { return; }
            var note = noteFor(pane, keyOf(ref));
            if (!note) { return; }
            e.preventDefault();
            flash(pane, note, keyOf(ref));
        });
        /* Tabbing onto a place name in the prose highlights it on the map, the
         * keyboard equivalent of hovering. */
        pane.addEventListener('focusin', function (e) {
            var ref = e.target.closest ? e.target.closest('.geo-ref') : null;
            if (ref) { highlight(pane, [keyOf(ref)], true); }
        });
        pane.addEventListener('focusout', function (e) {
            var ref = e.target.closest ? e.target.closest('.geo-ref') : null;
            if (ref) { highlight(pane, [keyOf(ref)], false); }
        });
    }

    function keyOf(el) {
        if (el.classList.contains('geo-ref')) {
            return (el.getAttribute('href') || '').replace(/^#geo-note-/, '');
        }
        return el.getAttribute('data-place') || '';
    }

    function flash(pane, note, key) {
        highlight(pane, [key], true);
        window.setTimeout(function () { highlight(pane, [key], false); }, 1600);
        if (note.scrollIntoView) {
            note.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
        }
    }

    /* --------------------------------------------------------------- boot */

    var CSS = '__CSS__';

    function styles() {
        if (document.getElementById('mapgeo-css')) { return; }
        var s = document.createElement('style');
        s.id = 'mapgeo-css';
        s.textContent = CSS;
        document.head.appendChild(s);
    }

    function start() {
        var els = document.querySelectorAll('.geo-map');
        if (!els.length) { return; }
        styles();
        var i;
        for (i = 0; i < els.length; i++) {
            var el = els[i];
            var pane = el.closest ? el.closest('.tab-content') || el.parentNode : el.parentNode;
            if (!pane.hasAttribute('data-geo-wired')) {
                pane.setAttribute('data-geo-wired', '1');
                wire(pane);
            }
            render(el);
            /* One observer per element, however many times start() runs. */
            if (!el.hasAttribute('data-geo-observed')) {
                el.setAttribute('data-geo-observed', '1');
                observe(el);
            }
        }
    }

    function observe(el) {
        /* The pane is display:none until its tab is opened, so the first useful
         * width arrives long after load. This also handles rotation and the
         * desktop sidebar opening. */
        if (typeof ResizeObserver === 'undefined') {
            window.addEventListener('resize', debounce(function () { render(el); }, 150));
            return;
        }
        var ro = new ResizeObserver(debounce(function () {
            var w = Math.round(el.clientWidth);
            if (w && String(w) !== el.getAttribute('data-rendered')) { render(el); }
        }, 120));
        ro.observe(el);
    }

    function debounce(fn, ms) {
        var t = null;
        return function () {
            window.clearTimeout(t);
            t = window.setTimeout(fn, ms);
        };
    }

    /* Panes are in the HTML, so the load-time pass finds everything. refresh()
     * exists for anything that adds a .geo-map afterwards, and is what the
     * stress test in WORKFLOW.md drives 831 real place lists through. */
    window.MapGeo = { refresh: start };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', start);
    } else {
        start();
    }
}());
